### 1. **Install Dependencies**

First, install the necessary packages:

```bash
npm install @tiptap/react @tiptap/starter-kit @tiptap/extension-image @tiptap/extension-placeholder
```

---

### 2. **Create the Tiptap Editor Component**

Create a new component, e.g., `RadiologistEditor.jsx`:

```jsx
// components/RadiologistEditor.jsx
import React, { useEffect } from 'react'
import { useEditor, EditorContent } from '@tiptap/react'
import StarterKit from '@tiptap/starter-kit'
import Image from '@tiptap/extension-image'
import Placeholder from '@tiptap/extension-placeholder'

const RadiologistEditor = ({ content, onChange }) => {
  const editor = useEditor({
    extensions: [
      StarterKit,
      Image,
      Placeholder.configure({
        placeholder: 'Start typing your report or annotations...',
      }),
    ],
    content,
    onUpdate: ({ editor }) => {
      if (onChange) {
        onChange(editor.getHTML())
      }
    },
  })

  // Optional: handle cleanup
  useEffect(() => {
    return () => {
      if (editor) {
        editor.destroy()
      }
    }
  }, [editor])

  // Function to handle image uploads
  const addImage = () => {
    const url = prompt('Enter image URL or upload your image')
    if (url) {
      editor.chain().focus().setImage({ src: url }).run()
    }
  }

  return (
    <div className="border rounded p-4 shadow-lg bg-white max-w-3xl mx-auto">
      {/* Toolbar */}
      <div className="flex space-x-2 mb-4">
        <button
          onClick={() => editor.chain().focus().toggleBold().run()}
          className={editor.isActive('bold') ? 'font-bold' : ''}
        >
          Bold
        </button>
        <button
          onClick={() => editor.chain().focus().toggleItalic().run()}
          className={editor.isActive('italic') ? 'italic' : ''}
        >
          Italic
        </button>
        <button
          onClick={() => editor.chain().focus().toggleHeading({ level: 2 }).run()}
          className={editor.isActive('heading', { level: 2 }) ? 'font-semibold' : ''}
        >
          H2
        </button>
        <button onClick={addImage}>Add Image</button>
        {/* Add more tools as needed */}
      </div>

      {/* Editor Content */}
      <EditorContent editor={editor} className="prose max-w-none" />
    </div>
  )
}

export default RadiologistEditor
```

