<canvas id="canvas"></canvas>
<script>
const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');

let width = window.innerWidth;
let height = window.innerHeight;
canvas.width = width;
canvas.height = height;

window.addEventListener('resize', () => {
  width = window.innerWidth;
  height = window.innerHeight;
  canvas.width = width;
  canvas.height = height;
});

// Parameters for fluid simulation
const gridSize = 100; // number of cells in grid (both x and y)
const cellSize = Math.min(width, height) / gridSize;
const density = [];
const velocityX = [];
const velocityY = [];
const newDensity = [];
const newVx = [];
const newVy = [];

// Initialize grids
for (let i = 0; i < gridSize; i++) {
  density[i] = [];
  velocityX[i] = [];
  velocityY[i] = [];
  newDensity[i] = [];
  newVx[i] = [];
  newVy[i] = [];
  for (let j = 0; j < gridSize; j++) {
    density[i][j] = 0;
    velocityX[i][j] = 0;
    velocityY[i][j] = 0;
    newDensity[i][j] = 0;
    newVx[i][j] = 0;
    newVy[i][j] = 0;
  }
}

// Function to add fluid source at a position
function addSource(x, y, amount) {
  const i = Math.floor(x * gridSize);
  const j = Math.floor(y * gridSize);
  if (i >= 0 && i < gridSize && j >= 0 && j < gridSize) {
    density[i][j] += amount;
    // Add some initial velocity for swirling effect
    const angle = Math.random() * Math.PI * 2;
    velocityX[i][j] += Math.cos(angle) * 2;
    velocityY[i][j] += Math.sin(angle) * 2;
  }
}

// Diffuse function
function diffuse(b, x, x0, diff, dt) {
  const a = dt * diff * gridSize * gridSize;
  for (let k = 0; k < 20; k++) {
    for (let i = 1; i < gridSize - 1; i++) {
      for (let j = 1; j < gridSize - 1; j++) {
        x[i][j] = (x0[i][j] + a * (x[i-1][j] + x[i+1][j] + x[i][j-1] + x[i][j+1])) / (1 + 4 * a);
      }
    }
    // Boundary conditions
    setBoundary(b, x);
  }
}

// Advect function
function advect(b, d, d0, velocX, velocY, dt) {
  const dt0 = dt * gridSize;
  for (let i = 1; i < gridSize - 1; i++) {
    for (let j = 1; j < gridSize - 1; j++) {
      let x = i - dt0 * velocX[i][j];
      let y = j - dt0 * velocY[i][j];

      if (x < 0.5) x = 0.5;
      if (x > gridSize - 1.5) x = gridSize - 1.5;
      const i0 = Math.floor(x);
      const i1 = i0 + 1;

      if (y < 0.5) y = 0.5;
      if (y > gridSize - 1.5) y = gridSize - 1.5;
      const j0 = Math.floor(y);
      const j1 = j0 + 1;

      const s1 = x - i0;
      const s0 = 1 - s1;
      const t1 = y - j0;
      const t0 = 1 - t1;

      d[i][j] = s0 * (t0 * d0[i0][j0] + t1 * d0[i0][j1]) +
                s1 * (t0 * d0[i1][j0] + t1 * d0[i1][j1]);
    }
  }
  setBoundary(b, d);
}

// Set boundary conditions
function setBoundary(b, x) {
  for (let i = 1; i < gridSize - 1; i++) {
    x[i][0] = b === 2 ? -x[i][1] : x[i][1];
    x[i][gridSize - 1] = b === 2 ? -x[i][gridSize - 2] : x[i][gridSize - 2];
  }
  for (let j = 1; j < gridSize - 1; j++) {
    x[0][j] = b === 1 ? -x[1][j] : x[1][j];
    x[gridSize - 1][j] = b === 1 ? -x[gridSize - 2][j] : x[gridSize - 2][j];
  }
  x[0][0] = 0.5 * (x[1][0] + x[0][1]);
  x[0][gridSize - 1] = 0.5 * (x[1][gridSize - 1] + x[0][gridSize - 2]);
  x[gridSize - 1][0] = 0.5 * (x[gridSize - 2][0] + x[gridSize - 1][1]);
  x[gridSize - 1][gridSize - 1] = 0.5 * (x[gridSize - 2][gridSize - 1] + x[gridSize - 1][gridSize - 2]);
}

// Main simulation step
function step() {
  // Add random swirling sources
  addSource(Math.random(), Math.random(), 0.2);

  // Diffuse velocities
  diffuse(1, newVx, velocityX, 0.0001, 0.1);
  diffuse(2, newVy, velocityY, 0.0001, 0.1);

  // Project velocities to be divergence-free
  project(newVx, newVy, velocityX, velocityY);

  // Advect velocities
  advect(1, velocityX, newVx, newVx, newVy, 0.1);
  advect(2, velocityY, newVy, newVx, newVy, 0.1);

  // Project again
  project(velocityX, velocityY, newVx, newVy);

  // Add density sources
  addSource(Math.random(), Math.random(), 1);

  // Diffuse density
  diffuse(0, newDensity, density, 0.0001, 0.1);
  // Advect density
  advect(0, density, newDensity, velocityX, velocityY, 0.1);

  // Swap buffers
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      density[i][j] = newDensity[i][j];
      velocityX[i][j] = newVx[i][j];
      velocityY[i][j] = newVy[i][j];
    }
  }
}

// Projection to make velocity divergence-free
function project(velocX, velocY, p, div) {
  for (let i = 1; i < gridSize - 1; i++) {
    for (let j = 1; j < gridSize - 1; j++) {
      div[i][j] = -0.5 * (velocX[i+1][j] - velocX[i-1][j] + velocY[i][j+1] - velocY[i][j-1]) / gridSize;
      p[i][j] = 0;
    }
  }
  setBoundary(0, div);
  setBoundary(0, p);

  for (let k = 0; k < 20; k++) {
    for (let i = 1; i < gridSize - 1; i++) {
      for (let j = 1; j < gridSize - 1; j++) {
        p[i][j] = (div[i][j] + p[i-1][j] + p[i+1][j] + p[i][j-1] + p[i][j+1]) / 4;
      }
    }
    setBoundary(0, p);
  }

  for (let i = 1; i < gridSize - 1; i++) {
    for (let j = 1; j < gridSize - 1; j++) {
      velocX[i][j] -= 0.5 * (p[i+1][j] - p[i-1][j]) * gridSize;
      velocY[i][j] -= 0.5 * (p[i][j+1] - p[i][j-1]) * gridSize;
    }
  }
  setBoundary(1, velocX);
  setBoundary(2, velocY);
}

// Animation loop
function animate() {
  ctx.clearRect(0, 0, width, height);
  step();

  // Draw density as colored pixels
  const imageData = ctx.getImageData(0, 0, width, height);
  const data = imageData.data;

  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      const x = Math.floor(i * cellSize);
      const y = Math.floor(j * cellSize);
      const index = (x + y * width) * 4;
      const d = Math.min(255, Math.max(0, density[i][j] * 255));
      // Color based on density
      data[index] = d; // R
      data[index + 1] = d * 0.5; // G
      data[index + 2] = 255 - d; // B
      data[index + 3] = 255; // alpha
    }
  }
  ctx.putImageData(imageData, 0, 0);

  requestAnimationFrame(animate);
}

// Start animation
animate();
</script>
</body>
