</style>
</head>
<body>
<canvas id="cradle" width="800" height="400"></canvas>

<script>
const canvas = document.getElementById('cradle');
const ctx = canvas.getContext('2d');

const NUM_SPHERES = 5;
const spheres = [];
const radius = 20;
const spacing = 80; // space between spheres
const originY = 150; // vertical position of the frame
const frameY = originY + 50; // y position of the frame
const frameHeight = 10;
const frameWidth = spacing * (NUM_SPHERES - 1) + 2 * radius;

let isDragging = false;
let dragSphereIndex = 0; // index of the sphere being dragged
let mouseX = 0;
let mouseY = 0;

// Initialize spheres
for (let i = 0; i < NUM_SPHERES; i++) {
  spheres.push({
    x: 100 + i * spacing,
    y: originY,
    vx: 0,
    vy: 0,
    angle: 0,
    angularVelocity: 0,
    isMoving: false,
    isDragged: false,
  });
}

// Helper functions
function drawFrame() {
  ctx.fillStyle = '#555';
  ctx.fillRect(0, frameY, canvas.width, frameHeight);
}

function drawSpheres() {
  ctx.fillStyle = '#999';
  spheres.forEach((sphere, index) => {
    // Calculate the position of the sphere based on its angle
    const length = 100; // length of the string/rod
    const angle = sphere.angle;
    const x = sphere.x + Math.sin(angle) * length;
    const y = sphere.y + Math.cos(angle) * length;

    sphere.currentX = x;
    sphere.currentY = y;

    // Draw string
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(sphere.x, sphere.y);
    ctx.lineTo(x, y);
    ctx.stroke();

    // Draw sphere
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fill();
  });
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawFrame();
  drawSpheres();
}

// Physics parameters
const gravity = 0.4;
const damping = 0.99; // energy loss factor

// Animate function
function animate() {
  spheres.forEach((sphere, index) => {
    if (sphere.isDragged) {
      // When dragging, set the angle based on mouse position
      const dx = mouseX - sphere.x;
      const dy = mouseY - sphere.y;
      sphere.angle = Math.atan2(dx, dy) - Math.PI / 2;
