    const s1 = spheres[i];
    const s2 = spheres[i + 1];

    // Calculate the positions
    const x1 = s1.currentX;
    const y1 = s1.currentY;
    const x2 = s2.currentX;
    const y2 = s2.currentY;

    const dx = x2 - x1;
    const dy = y2 - y1;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (dist < 2 * radius * 0.9) { // collision threshold
      // Swap angular velocities for elastic collision
      const temp = s1.angularVelocity;
      s1.angularVelocity = s2.angularVelocity;
      s2.angularVelocity = temp;
    }
