Certainly! Here's a complete example of a 2D simulation of Newton's Cradle using HTML, CSS, and JavaScript. This implementation features five identical metallic spheres suspended from a simple frame. When you click and drag the leftmost sphere, it swings and hits the others, demonstrating the transfer of momentum and energy.

---

### Features:
- **Minimalist design** with clean lines and metallic spheres.
- **Interactive**: Drag the first sphere to set it in motion.
- **Realistic physics**: Uses simple pendulum physics for smooth, natural motion.
- **Accurate**: Demonstrates conservation principles.

---

## Complete Code

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>Newton's Cradle Simulation</title>
<style>
  body {
    margin: 0;
    background: #f0f0f0;
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;
  }

  svg {
    background: #fff;
    border: 2px solid #333;
    border-radius: 8px;
  }

  /* Optional: Cursor change when dragging */
  .draggable {
    cursor: grab;
  }
  .dragging {
    cursor: grabbing;
  }
</style>
</head>
<body>

<svg id="cradle" width="800" height="400"></svg>

<script>
  const svg = document.getElementById('cradle');

  // Configuration
  const numSpheres = 5;
  const sphereRadius = 20;
  const spacing = 60; // space between spheres
  const frameHeight = 100;
  const frameWidth = 800;
  const topMargin = 50;

  // Arrays to hold sphere data
  const spheres = [];
  const strings = [];

  // Create frame
  const frame = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
  frame.setAttribute('x', 50);
  frame.setAttribute('y', topMargin - 20);
  frame.setAttribute('width', frameWidth - 100);
  frame.setAttribute('height', frameHeight);
  frame.setAttribute('fill', 'none');
  frame.setAttribute('stroke', '#555');
  frame.setAttribute('stroke-width', '4');
  svg.appendChild(frame);

  // Initialize spheres
  const startX = 150;
  const centerY = topMargin + frameHeight + 50;

  for (let i = 0; i < numSpheres; i++) {
    const x = startX + i * spacing;
    const y = centerY;

    // Create string
    const string = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    string.setAttribute('x1', x);
    string.setAttribute('y1', topMargin);
    string.setAttribute('x2', x);
    string.setAttribute('y2', y - sphereRadius);
    string.setAttribute('stroke', '#555');
    string.setAttribute('stroke-width', '2');
    svg.appendChild(string);
    strings.push(string);

    // Create sphere
    const sphere = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    sphere.setAttribute('cx', x);
    sphere.setAttribute('cy', y);
    sphere.setAttribute('r', sphereRadius);
    sphere.setAttribute('fill', '#bbb');
    sphere.setAttribute('stroke', '#555');
    sphere.setAttribute('stroke-width', '2');
    sphere.style.cursor = 'grab';

    // Store physics properties
    const angleLimit = Math.PI / 4; // max swing angle (45 degrees)
    spheres.push({
      element: sphere,
      string: string,
      originX: x,
      originY: topMargin,
      length: y - topMargin,
      angle: 0,
      angularVelocity: 0,
      isDragging: false,
      dragStartX: 0,
      dragStartY: 0,
      mass: 1,
      radius: sphereRadius,
      color: '#bbb'
    });

    svg.appendChild(sphere);
  }

  // Variables for animation
  let lastTime = null;
  const damping = 0.999; // damping factor for energy loss (simulate friction)

  // Dragging variables
  let draggedSphere = null;

  // Add event listeners for dragging
  spheres.forEach((sphereData, index) => {
    const sphere = sphereData.element;

    sphere.addEventListener('mousedown', (e) => {
      if (index === 0) { // only allow dragging the first sphere
        sphereData.isDragging = true;
        sphere.style.cursor = 'grabbing';
        draggedSphere = sphereData;
        sphereData.dragStartX = e.clientX;
        sphereData.dragStartY = e.clientY;
        e.preventDefault();
      }
    });
  });

  document.addEventListener('mouseup', () => {
    if (draggedSphere) {
      // Convert drag displacement to initial angle
      const dx = draggedSphere.dragStartX - lastMouseX;
      const dy = draggedSphere.dragStartY - lastMouseY;
      // Calculate angle based on displacement
      const deltaX = lastMouseX - draggedSphere.originX;
      const deltaY = lastMouseY - draggedSphere.originY;
      const angle = Math.atan2(deltaY, deltaX);
      // Limit angle
      draggedSphere.angle = Math.max(-Math.PI / 4, Math.min(Math.PI / 4, angle));
      // Set initial angular velocity based on drag speed
      // For simplicity, set to zero here
      draggedSphere.angularVelocity = 0;
      draggedSphere.isDragging = false;
      draggedSphere.element.style.cursor = 'grab';
      draggedSphere = null;
    }
  });

  let lastMouseX = 0;
  let lastMouseY = 0;

  document.addEventListener('mousemove', (e) => {
    lastMouseX = e.clientX;
    lastMouseY = e.clientY;
    if (draggedSphere && draggedSphere.isDragging) {
      // Calculate angle from origin to mouse position
      const dx = e.clientX - draggedSphere.originX;
      const dy = e.clientY - draggedSphere.originY;
      let angle = Math.atan2(dy, dx);
      // Limit the angle
      angle = Math.max(-draggedSphere.angleLimit, Math.min(draggedSphere.angleLimit, angle));
      draggedSphere.angle = angle;
    }
  });

  // Initialize the first sphere with a displaced angle
  // For demonstration, you can also click and drag to set initial displacement

  // Animation loop
  function animate(timestamp) {
    if (!lastTime) lastTime = timestamp;
    const delta = (timestamp - lastTime) / 1000; // seconds
    lastTime = timestamp;

    // Update physics for each sphere
    for (let i = 0; i < spheres.length; i++) {
      const s = spheres[i];

      if (s.isDragging) {
        // During dragging, update position based on current angle
        const x = s.originX + s.length * Math.sin(s.angle);
        const y = s.originY + s.length * Math.cos(s.angle);
        s.element.setAttribute('cx', x);
        s.element.setAttribute('cy', y);
        s.string.setAttribute('x2', x);
        s.string.setAttribute('y2', y - s.radius);
        continue;
      }

      if (i === 0 && !s.isDragging) {
        // Apply physics for the first sphere (pendulum)
        // Simple pendulum physics
        const gravity = 9.81;
        const angularAcceleration = -(gravity / s.length) * Math.sin(s.angle);
        s.angularVelocity += angularAcceleration * delta;
        s.angularVelocity *= damping; // damping
        s.angle += s.angularVelocity * delta;

        // Limit angle to prevent unrealistic swings
        if (s.angle > s.angleLimit) {
          s.angle = s.angleLimit;
          s.angularVelocity *= -0.5;
        } else if (s.angle < -s.angleLimit) {
          s.angle = -s.angleLimit;
          s.angularVelocity *= -0.5;
        }
      } else {
        // For other spheres, check for collision with previous sphere
        // and transfer momentum if collision occurs
        // Simplified collision detection based on positions
        const prev = spheres[i - 1];
        const curr = s;

        // Calculate current position
        const x = curr.originX + curr.length * Math.sin(curr.angle);
        const y = curr.originY + curr.length * Math.cos(curr.angle);

        // Check collision with previous sphere
        const prevX = prev.element.getAttribute('cx');
        const prevY = prev.element.getAttribute('cy');

        const dx = x - prevX;
        const dy = y - prevY;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist < 2 * s.radius && Math.abs(prev.angularVelocity) > 0.01) {
          // Transfer momentum: simple exchange of velocities
          // For perfect elastic collision, swap angular velocities
          const temp = prev.angularVelocity;
          prev.angularVelocity = curr.angularVelocity;
          curr.angularVelocity = temp;
        }
      }

      // Update sphere position based on angle
      const x = s.originX + s.length * Math.sin(s.angle);
      const y = s.originY + s.length * Math.cos(s.angle);
      s.element.setAttribute('cx', x);
      s.element.setAttribute('cy', y);
      s.string.setAttribute('x2', x);
      s.string.setAttribute('y2', y - s.radius);
    }

    requestAnimationFrame(animate);
  }

  // Start animation
  requestAnimationFrame(animate);
</script>

</body>
</html>
```

