### Complete Script:

```csharp
using UnityEngine;
using UnityEditor;

public class SetSortingLayer : EditorWindow
{
    private string[] sortingLayerNames;
    private int selectedLayerIndex = 0;

    [MenuItem("Window/Set Sorting Layer")]
    public static void ShowWindow()
    {
        GetWindow<SetSortingLayer>("Set Sorting Layer");
    }

    private void OnEnable()
    {
        // Retrieve all sorting layer names
        sortingLayerNames = GetSortingLayerNames();

        // Optionally, set default selection to the first layer
        if (sortingLayerNames.Length > 0)
        {
            selectedLayerIndex = 0;
        }
    }

    private void OnGUI()
    {
        GUILayout.Label("Select Sorting Layer", EditorStyles.boldLabel);

        if (sortingLayerNames.Length == 0)
        {
            EditorGUILayout.HelpBox("No sorting layers found. Please ensure sorting layers are defined.", MessageType.Warning);
            return;
        }

        // Dropdown for selecting sorting layer
        selectedLayerIndex = EditorGUILayout.Popup("Sorting Layer", selectedLayerIndex, sortingLayerNames);

        GUILayout.Space(10);

        if (GUILayout.Button("Apply to Selected"))
        {
            ApplySortingLayerToSelected();
        }
    }

    private string[] GetSortingLayerNames()
    {
        // Retrieve all sorting layer names
        return SortingLayer.layers.Select(layer => layer.name).ToArray();
    }

    private void ApplySortingLayerToSelected()
    {
        if (sortingLayerNames.Length == 0)
        {
            Debug.LogWarning("No sorting layers available to assign.");
            return;
        }

        string targetLayer = sortingLayerNames[selectedLayerIndex];

        // Get selected GameObjects
        GameObject[] selectedObjects = Selection.gameObjects;

        if (selectedObjects.Length == 0)
        {
            Debug.LogWarning("No GameObjects selected.");
            return;
        }

        int appliedCount = 0;

        foreach (GameObject go in selectedObjects)
        {
            bool updated = false;

            // Get all Renderer components in the GameObject and its children
            Renderer[] renderers = go.GetComponentsInChildren<Renderer>(true);

            foreach (Renderer renderer in renderers)
            {
                // Check if the renderer has a sortingLayerName property
                // Since Renderer has a property 'sortingLayerName', we can set it directly
                if (renderer != null)
                {
                    Undo.RecordObject(renderer, "Set Sorting Layer");
                    renderer.sortingLayerName = targetLayer;
                    EditorUtility.SetDirty(renderer);
                    updated = true;
                }
            }

            if (updated)
            {
                appliedCount++;
            }
        }

        Debug.Log($"Applied sorting layer '{targetLayer}' to {appliedCount} GameObject(s).");
    }
}
```

