```csharp
using System;
using System.IO;
using System.Collections.Generic;
using SAPbobsCOM; // Reference to SAP Business One DI API

namespace SAPVolumeDiscountUpdater
{
    class Program
    {
        // Path to your CSV file
        private const string CsvFilePath = @"C:\path\to\volume_discounts.csv";

        static void Main(string[] args)
        {
            // Initialize SAP DI API connection
            Company oCompany = new Company();

            // Set your SAP B1 connection details
            oCompany.Server = "YOUR_SERVER";
            oCompany.DbServerType = BoDataServerTypes.dst_MSSQL2014; // or your DB type
            oCompany.CompanyDB = "YOUR_COMPANY_DB";
            oCompany.UserName = "manager";
            oCompany.Password = "password";

            try
            {
                if (oCompany.Connect() != 0)
                {
                    int errorCode;
                    string errorMsg;
                    oCompany.GetLastError(out errorCode, out errorMsg);
                    Console.WriteLine($"Failed to connect to SAP Business One: {errorMsg}");
                    return;
                }
                Console.WriteLine("Connected to SAP Business One.");

                // Read CSV data
                var discounts = ReadDiscountsFromCsv(CsvFilePath);

                // Process each discount
                foreach (var discount in discounts)
                {
                    UpdateOrAddSpecialPrice(oCompany, discount);
                }

                Console.WriteLine("Processing completed.");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error: {ex.Message}");
            }
            finally
            {
                if (oCompany.Connected)
                {
                    oCompany.Disconnect();
                }
            }
        }

        // Data structure for discounts
        public class VolumeDiscount
        {
            public string ItemCode { get; set; }
            public int PriceList { get; set; }
            public double MinQuantity { get; set; }
            public double Price { get; set; }
        }

        // Reads CSV and returns list of discounts
        static List<VolumeDiscount> ReadDiscountsFromCsv(string filePath)
        {
            var list = new List<VolumeDiscount>();
            using (var reader = new StreamReader(filePath))
            {
                string headerLine = reader.ReadLine(); // Skip header
                while (!reader.EndOfStream)
                {
                    var line = reader.ReadLine();
                    var parts = line.Split(',');

                    if (parts.Length >= 4)
                    {
                        var discount = new VolumeDiscount
                        {
                            ItemCode = parts[0].Trim(),
                            PriceList = int.Parse(parts[1].Trim()),
                            MinQuantity = double.Parse(parts[2].Trim()),
                            Price = double.Parse(parts[3].Trim())
                        };
                        list.Add(discount);
                    }
                }
            }
            return list;
        }

        // Updates or adds special prices in SAP B1
        static void UpdateOrAddSpecialPrice(Company company, VolumeDiscount discount)
        {
            // Access the PriceLists object
            PriceLists priceLists = (PriceLists)company.GetBusinessObject(BoObjectTypes.oPriceLists);
            if (priceLists.GetByKey(discount.PriceList))
            {
                // Price list exists, proceed
            }
            else
            {
                Console.WriteLine($"Price list {discount.PriceList} not found.");
                return;
            }

            // Access the PriceListItems collection
            PriceListItems priceListItems = (PriceListItems)priceLists.PriceListItems;

            // Check if a special price for the item and min quantity exists
            bool found = false;
            for (int i = 0; i < priceListItems.Count; i++)
            {
                priceListItems.SetCurrentLine(i);
                if (priceListItems.ItemCode == discount.ItemCode && priceListItems.MinQuantity == discount.MinQuantity)
                {
                    // Update existing special price
                    priceListItems.Price = discount.Price;
                    priceListItems.Update();
                    Console.WriteLine($"Updated special price for Item {discount.ItemCode} at MinQty {discount.MinQuantity} in PriceList {discount.PriceList}.");
                    found = true;
                    break;
                }
            }

            if (!found)
            {
                // Add new special price
                priceListItems.Add();
                int newIndex = priceListItems.Count - 1;
                priceListItems.SetCurrentLine(newIndex);
                priceListItems.ItemCode = discount.ItemCode;
                priceListItems.MinQuantity = discount.MinQuantity;
                priceListItems.Price = discount.Price;
                priceListItems.Update();
                Console.WriteLine($"Added new special price for Item {discount.ItemCode} at MinQty {discount.MinQuantity} in PriceList {discount.PriceList}.");
            }

            // Save changes
            priceLists.Update();
        }
    }
}
