      tr.className = entry.known ? 'known' : 'unknown';

      // Word cell
      const tdWord = document.createElement('td');
      tdWord.textContent = entry.word;
      tr.appendChild(tdWord);

      // Definition cell
      const tdDef = document.createElement('td');
      tdDef.textContent = entry.definition;
      tr.appendChild(tdDef);

      // Known checkbox
      const tdKnown = document.createElement('td');
      const knownCheckbox = document.createElement('input');
      knownCheckbox.type = 'checkbox';
      knownCheckbox.checked = entry.known;
      knownCheckbox.onclick = () => {
        entry.known = knownCheckbox.checked;
        saveVocabulary();
        renderVocabulary();
      };
      tdKnown.appendChild(knownCheckbox);
      tr.appendChild(tdKnown);

      // Edit button
      const tdEdit = document.createElement('td');
      const editBtn = document.createElement('button');
      editBtn.textContent = 'Edit';
      editBtn.onclick = () => {
        editVocabulary(index);
      };
      tdEdit.appendChild(editBtn);
      tr.appendChild(tdEdit);

      // Delete button
      const tdDelete = document.createElement('td');
      const delBtn = document.createElement('button');
      delBtn.textContent = 'Delete';
      delBtn.onclick = () => {
        if (confirm(`Delete "${entry.word}"?`)) {
          vocabulary.splice(index, 1);
          saveVocabulary();
          renderVocabulary();
        }
      };
      tdDelete.appendChild(delBtn);
      tr.appendChild(tdDelete);

      tbody.appendChild(tr);
    });
  }

  // Add new vocabulary
  function addVocabulary() {
    const wordInput = document.getElementById('newWord');
    const defInput = document.getElementById('newDefinition');
    const word = wordInput.value.trim();
    const definition = defInput.value.trim();

    if (!word || !definition) {
      alert('Please enter both word and definition.');
      return;
    }

    // Check for duplicates
    if (vocabulary.some(v => v.word.toLowerCase() === word.toLowerCase())) {
      alert('Word already exists.');
      return;
    }

    vocabulary.push({ word, definition, known: false });
    saveVocabulary();
    wordInput.value = '';
    defInput.value = '';
    renderVocabulary();
  }

  // Edit vocabulary entry
  function editVocabulary(index) {
    const entry = vocabulary[index];
    const newWord = prompt('Edit Word:', entry.word);
    if (newWord === null) return; // Cancel
    const newDef = prompt('Edit Definition:', entry.definition);
    if (newDef === null) return;

    // Check for duplicate word if changed
    if (newWord.trim() && newWord.trim().toLowerCase() !== entry.word.toLowerCase()) {
      if (vocabulary.some((v, i) => v.word.toLowerCase() === newWord.trim().toLowerCase() && i !== index)) {
        alert('Another entry with this word exists.');
        return;
      }
    }

    if (newWord.trim()) entry.word = newWord.trim();
    if (newDef.trim()) entry.definition = newDef.trim();

    saveVocabulary();
    renderVocabulary();
  }

  // Start the test
  function startTest() {
    loadVocabulary();
    const excludeKnown = document.getElementById('excludeKnown').checked;
    // Filter words for testing
    currentTestWords = vocabulary.filter(v => !(excludeKnown && v.known));
    if (currentTestWords.length === 0) {
      alert('No vocabulary available for testing. Adjust your filters.');
      return;
    }
    // Shuffle the words
    currentTestWords = shuffleArray(currentTestWords);
    currentQuestionIndex = 0;
    score = 0;
    document.getElementById('score').textContent = score;
    document.getElementById('total').textContent = currentTestWords.length;
    document.getElementById('testSection').classList.remove('hidden');
    showQuestion();
  }

  // Shuffle array helper
  function shuffleArray(array) {
    let arr = array.slice();
    for (let i = arr.length -1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i+1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  // Show current question
  function showQuestion() {
    document.getElementById('feedback').textContent = '';
    document.getElementById('answerInput').value = '';
    if (currentQuestionIndex >= currentTestWords.length) {
      alert(`Test completed! Your score: ${score} / ${currentTestWords.length}`);
      document.getElementById('testSection').classList.add('hidden');
      return;
    }
    const currentWord = currentTestWords[currentQuestionIndex];
    document.getElementById('question').textContent = `Define: ${currentWord.word}`;
  }

  // Submit answer
  function submitAnswer() {
    const answer = document.getElementById('answerInput').value.trim();
    const currentWord = currentTestWords[currentQuestionIndex];

    if (!answer) {
      alert('Please enter an answer.');
      return;
    }

    // Check answer (case-insensitive)
    if (answer.toLowerCase() === currentWord.definition.toLowerCase()) {
      document.getElementById('feedback').textContent = 'Correct!';
      score++;
      document.getElementById('score').textContent = score;
    } else {
      document.getElementById('feedback').textContent = `Incorrect! Definition: ${currentWord.definition}`;
    }

    currentQuestionIndex++;
    setTimeout(showQuestion, 1000);
  }

  // Initialize app
  loadVocabulary();
  renderVocabulary();

</script>

</body>
</html>
```

### How it works:

- **Adding Vocabulary:** Enter a word and its definition, then click "Add".
- **Editing Vocabulary:** Click "Edit" next to a word to modify it.
- **Deleting Vocabulary:** Click "Delete" to remove an entry.
- **Marking Known:** Check or uncheck the "Known" box to mark vocabulary as known or unknown.
- **Filtering:** Use the "Exclude Known Vocabulary" checkbox to hide known words during testing.
- **Testing:** Click "Start Test" to begin. The app will prompt you with words and check your answers, updating your score.

### Storage:
All data is stored locally in your browser's `localStorage`, so your vocabulary persists across sessions.

