      label: {
        default: 'Annotation',
      },
    }
  },
  parseHTML() {
    return [
      {
        tag: 'span[data-annotation]',
      },
    ]
  },
  renderHTML({ HTMLAttributes }) {
    return ['span', { 'data-annotation': true, style: 'background-color: yellow; cursor: pointer;', 'data-label': HTMLAttributes.label }, 0]
  },
