  const birdGeometry = new THREE.BoxGeometry(0.3,0.3,0.3);
  const birdMaterial = new THREE.MeshStandardMaterial({color:0xffcc00});
  bird = new THREE.Mesh(birdGeometry, birdMaterial);
  bird.position.set(0,1,0);
  scene.add(bird);

  for(let i=0; i<pipeCount; i++) {
    let topPipe = createPipe();
    let bottomPipe = createPipe();
    positionPipes(topPipe, bottomPipe, i);
    scene.add(topPipe);
    scene.add(bottomPipe);
    pipes.push({top: topPipe, bottom: bottomPipe, x: i*pipeSpacing});
  }

  window.addEventListener('resize', onWindowResize, false);
  window.addEventListener('mousedown', ()=>{mouseDown=true});
  window.addEventListener('mouseup', ()=>{mouseDown=false});
}

function createPipe() {
  const geometry = new THREE.BoxGeometry(pipeWidth,1,pipeWidth);
  const material = new THREE.MeshStandardMaterial({color:0x00ff00});
  return new THREE.Mesh(geometry, material);
}

function positionPipes(topPipe, bottomPipe, index) {
  let centerY = (Math.random() * 2 -1) * 1;
  topPipe.position.set(index*pipeSpacing, centerY + pipeGap/2 + 0.5, 0);
  bottomPipe.position.set(index*pipeSpacing, centerY - pipeGap/2 - 0.5, 0);
}

function onWindowResize() {
  camera.aspect = window.innerWidth/window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
}

function animate() {
  requestAnimationFrame(animate);
  if(!gameOver) {
    let delta = clock.getDelta();

    if(mouseDown) {
      velocity += lift;
    }
    velocity -= gravity;
    bird.position.y += velocity;

    if(bird.position.y < -2 || bird.position.y > 3) {
      endGame();
    }

    for(let i=0; i<pipes.length; i++) {
      pipes[i].x -= 0.02;
      pipes[i].top.position.x = pipes[i].x;
      pipes[i].bottom.position.x = pipes[i].x;

      if(pipes[i].x < -2) {
        pipes[i].x += pipeCount*pipeSpacing;
        let centerY = (Math.random() * 2 -1) * 1;
        pipes[i].top.position.set(pipes[i].x, centerY + pipeGap/2 + 0.5, 0);
        pipes[i].bottom.position.set(pipes[i].x, centerY - pipeGap/2 - 0.5, 0);
      }

      if(checkCollision(bird, pipes[i].top) || checkCollision(bird, pipes[i].bottom)) {
        endGame();
      }
    }

    camera.position.x += 0.005;
    camera.lookAt(bird.position.x + 1, bird.position.y, 0);
  }

  renderer.render(scene, camera);
}

function checkCollision(bird, pipe) {
  let box1 = new THREE.Box3().setFromObject(bird);
  let box2 = new THREE.Box3().setFromObject(pipe);
  return box1.intersectsBox(box2);
}

function endGame() {
  gameOver = true;
  alert("Game Over");
}
</script>
</body>
</html>
```

