```javascript
const canvas = document.getElementById('myCanvas');
const ctx = canvas.getContext('2d');

let imageLoaded = false;
let image = null;

// Resize canvas to fill window
function resizeCanvas() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    draw();
}

window.addEventListener('resize', resizeCanvas);

// Draw initial message or image
function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (!imageLoaded) {
        // Draw prompt message
        ctx.fillStyle = '#333';
        ctx.font = '24px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('Drag and drop an image here, or click to load one.', canvas.width / 2, canvas.height / 2);
    } else {
        // Draw the loaded image scaled to fit the canvas
        const aspectRatio = image.width / image.height;
        let drawWidth = canvas.width;
        let drawHeight = canvas.height;

        if (canvas.width / canvas.height > aspectRatio) {
            // Canvas is wider relative to image
            drawWidth = canvas.height * aspectRatio;
        } else {
            // Canvas is taller relative to image
            drawHeight = canvas.width / aspectRatio;
        }

        const offsetX = (canvas.width - drawWidth) / 2;
        const offsetY = (canvas.height - drawHeight) / 2;

        ctx.drawImage(image, offsetX, offsetY, drawWidth, drawHeight);
    }
}

// Handle file input via click
function handleFile(file) {
    if (file && file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onload = function(e) {
            const img = new Image();
            img.onload = function() {
                image = img;
                imageLoaded = true;
                draw();
            };
            img.src = e.target.result;
        };
        reader.readAsDataURL(file);
    }
}

// Trigger file input dialog
function triggerFileSelect() {
    if (imageLoaded) return; // Do nothing if image already loaded
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = () => {
        if (input.files.length > 0) {
            handleFile(input.files[0]);
        }
    };
    input.click();
}

// Drag-and-drop handlers
canvas.addEventListener('dragover', (e) => {
    e.preventDefault();
    e.stopPropagation();
    // Optional: add visual feedback
});

canvas.addEventListener('drop', (e) => {
    e.preventDefault();
    e.stopPropagation();
    const files = e.dataTransfer.files;
    if (files.length > 0) {
        handleFile(files[0]);
    }
});

// Click handler
canvas.addEventListener('click', () => {
    if (!imageLoaded) {
        triggerFileSelect();
    }
});

// Initialize
resizeCanvas();
draw();
```

---

### **Summary of Functionality**
- The canvas fills the entire viewport.
- Initially, it displays a message prompting the user to drag-and-drop or click.
- Drag-and-drop is always active; dropping an image loads it onto the canvas.
- Clicking on the canvas opens a file dialog to select an image, but only if no image has been loaded yet.
- Once an image is loaded, the message disappears, the image is scaled to fit the canvas, and clicking to load is disabled (click handler checks `imageLoaded`).

