Certainly! Here's a PowerShell script that recursively searches for Git repositories starting from a specified directory (or current directory if none specified), and for each repository found, it retrieves the date of its initial commit.

```powershell
# PowerShell script to find Git repositories recursively and get their initial commit date

param(
    [string]$StartPath = (Get-Location).Path
)

function Get-GitRepositories {
    param([string]$Path)

    # Find directories containing a .git folder
    Get-ChildItem -Path $Path -Recurse -Directory -Force -ErrorAction SilentlyContinue | Where-Object {
        Test-Path (Join-Path $_.FullName ".git")
    }
}

function Get-InitialCommitDate {
    param([string]$RepoPath)

    # Use git command to get the first commit date
    $gitLogCommand = 'git log --reverse --format=%cI --max-count=1'
    try {
        $initialCommitDate = & git -C $RepoPath $gitLogCommand 2>$null
        if ($initialCommitDate) {
            return $initialCommitDate.Trim()
        } else {
            return "No commits found"
        }
    } catch {
        return "Error retrieving commit"
    }
}

# Main script
$repositories = Get-GitRepositories -Path $StartPath

if ($repositories) {
    foreach ($repo in $repositories) {
        $repoPath = $repo.FullName
        $initialDate = Get-InitialCommitDate -RepoPath $repoPath
        Write-Output "Repository: $repoPath"
        Write-Output "Initial Commit Date: $initialDate"
        Write-Output "----------------------------------------"
    }
} else {
    Write-Output "No Git repositories found under $StartPath"
}
```

### How to use:
1. Save this script to a file, e.g., `Get-GitInitialCommits.ps1`.
2. Open PowerShell.
3. Run the script, optionally specifying a starting directory:
   ```powershell
   .\Get-GitInitialCommits.ps1 -StartPath "C:\Path\To\Search"
   ```
   Or just run it without parameters to search from the current directory:
   ```powershell
   .\Get-GitInitialCommits.ps1
   ```

### Notes:
- The script searches recursively for directories containing a `.git` folder.
- It uses `git log --reverse --format=%cI --max-count=1` to get the date of the first commit in ISO 8601 format.
- Ensure that Git is installed and available in your system's PATH.

