  padding: 5px;
}

#status {
  margin-top: 10px;
  font-size: 12px;
  color: green;
}
```

---

## Step 4: Main JavaScript Logic (`main.js`)

This script handles:

- Fetching voice list
- Handling user input
- Making API requests
- Downloading MP3
- Adding audio to AE timeline

### Note:
- Use `CSInterface` to communicate with After Effects.
- Use `fetch` for API calls.
- For file downloads, use `File` and `XMLHttpRequest` or `fetch` with blobs.

```js
(function () {
  const csInterface = new CSInterface();

  const apiKeyInput = document.getElementById('apiKey');
  const voiceSelect = document.getElementById('voiceSelect');
  const textInput = document.getElementById('textInput');
  const multiviewCheckbox = document.getElementById('multiview');
  const statusDiv = document.getElementById('status');
  const refreshBtn = document.getElementById('refreshVoices');

  let voices = [];

  // Load voices on startup
  document.addEventListener('DOMContentLoaded', () => {
    loadVoices();
  });

  // Refresh voices
  refreshBtn.onclick = () => {
    loadVoices();
  };

  // Load voices from API
  async function loadVoices() {
    const apiKey = apiKeyInput.value.trim();
    if (!apiKey) {
      updateStatus('Please enter API key.');
      return;
    }
    updateStatus('Loading voices...');
    try {
      const response = await fetch('https://api.elevenlabs.io/v1/voices', {
        headers: {
          'xi-api-key': apiKey,
        },
      });
      if (!response.ok) {
        throw new Error(`Error fetching voices: ${response.statusText}`);
      }
      voices = await response.json();
      populateVoiceSelect();
      updateStatus('Voices loaded.');
    } catch (err) {
      console.error(err);
      updateStatus('Failed to load voices.');
    }
  }

  function populateVoiceSelect() {
    voiceSelect.innerHTML = '';
    voices.forEach((voice) => {
      const option = document.createElement('option');
      option.value = voice.voice_id;
      option.textContent = voice.name;
      voiceSelect.appendChild(option);
    });
  }

  // Handle Enter key in textarea
  textInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      generateSpeech();
    }
  });

  // Generate speech
async function generateSpeech() {
  const apiKey = apiKeyInput.value.trim();
  const voiceId = voiceSelect.value;
  const text = textInput.value.trim();
  const isMultiview = multiviewCheckbox.checked;

  if (!apiKey || !voiceId || !text) {
    updateStatus('Please fill in all fields.');
    return;
  }

  updateStatus('Generating speech...');
  try {
    if (isMultiview) {
      // Send 3 concurrent requests
      const promises = [
        fetchAudio(apiKey, voiceId, text),
        fetchAudio(apiKey, voiceId, text),
        fetchAudio(apiKey, voiceId, text),
      ];
      const audioBlobs = await Promise.all(promises);
      // Add one or three to timeline
      // For simplicity, add all three
      for (let i = 0; i < audioBlobs.length; i++) {
        await addAudioToTimeline(audioBlobs[i], `V${i + 1}`);
      }
      updateStatus('Added 3 versions.');
    } else {
      const audioBlob = await fetchAudio(apiKey, voiceId, text);
      await addAudioToTimeline(audioBlob);
      updateStatus('Audio added.');
    }
  } catch (err) {
    console.error(err);
    updateStatus('Error generating speech.');
  }
}

// Fetch audio from ElevenLabs API
async function fetchAudio(apiKey, voiceId, text) {
  const response = await fetch(`https://api.elevenlabs.io/v1/text-to-speech/${voiceId}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'xi-api-key': apiKey,
    },
    body: JSON.stringify({
      text: text,
      voice_settings: {
        // Optional: add voice settings here
      },
    }),
  });
  if (!response.ok) {
    throw new Error(`API error: ${response.statusText}`);
  }
  const blob = await response.blob();
  return blob;
}

// Add audio blob to AE timeline
async function addAudioToTimeline(audioBlob, label = 'TTS') {
  // Save blob to temp file
  const tempFolder = Folder.tempFolder;
  const filename = `tts_${Date.now()}.mp3`;
  const filePath = tempFolder.fsName + '/' + filename;
  const file = new File(filePath);
  await saveBlobToFile(audioBlob, file);

  // Call ExtendScript to import and add to timeline
  csInterface.evalScript(`addAudioToComp("${file.fsName}", "${label}")`);
}

// Save blob to file
function saveBlobToFile(blob, file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const data = new Uint8Array(reader.result);
      file.encoding = 'BINARY';
      file.open('w');
      file.write(data);
      file.close();
      resolve();
    };
    reader.onerror = reject;
    reader.readAsArrayBuffer(blob);
  });
}

function updateStatus(msg) {
  statusDiv.textContent = msg;
}
})();
```

---

## Step 5: ExtendScript (`addAudioToComp.jsx`)

Create a separate ExtendScript file that AE runs to import the MP3 and add it to the timeline.

```jsx
function addAudioToComp(filePath, label) {
  var importOptions = new ImportOptions(new File(filePath));
  var importedFile = app.project.importFile(importOptions);
  var comp = app.project.activeItem;
  if (!(comp instanceof CompItem)) {
    alert("Please select or open a composition.");
    return;
  }
  var layer = comp.layers.add(importedFile);
  layer.name = label || "TTS Audio";
  // Optional: set in/out points, position, etc.
}
addAudioToComp($.evalFile('addAudioToComp.jsx'));
```

**Note:** You need to load this script into AE's scripting environment. Alternatively, you can embed the code directly in your main script or call `app.project.importFile()` directly from ExtendScript.

---

## Additional Tips

- **Authentication**: Use API keys for simplicity.
- **Error Handling**: Add more robust error handling.
- **UI Enhancements**: Add progress bars, voice preview, etc.
- **Packaging**: Bundle your CEP extension properly for distribution.

---

## Summary

This setup provides a starting point for integrating ElevenLabs TTS into After Effects via a custom panel. It allows voice selection, text input, concurrent requests, and adds generated audio as new layers in your composition.

---

**Disclaimer:** Make sure to comply with ElevenLabs API usage policies and handle API keys securely.

In CCS PCW C compiler, if you want to break down a 16-bit integer (`int16`) into its high and low bytes, and then reassemble it, you can do so using bitwise operations and type casting.

### Breaking down an `int16` into high and low bytes:

```c
#include <stdint.h> // For fixed-width types, optional depending on compiler

int16_t value = 0x1234; // Example 16-bit value

// Extract low byte (least significant 8 bits)
uint8_t low_byte = (uint8_t)(value & 0xFF);

// Extract high byte (most significant 8 bits)
uint8_t high_byte = (uint8_t)((value >> 8) & 0xFF);
```

### Reassembling the bytes into an `int16`:

```c
int16_t reassembled_value = (int16_t)((high_byte << 8) | low_byte);
```

### Complete example:

```c
#include <stdint.h>
#include <stdio.h>

int main() {
    int16_t original_value = 0x1234; // Example value

    // Break down
    uint8_t low_byte = (uint8_t)(original_value & 0xFF);
    uint8_t high_byte = (uint8_t)((original_value >> 8) & 0xFF);

    // Reassemble
    int16_t reassembled_value = (int16_t)((high_byte << 8) | low_byte);

    // Output for verification
    printf("Original: 0x%04X\n", original_value);
    printf("High byte: 0x%02X\n", high_byte);
    printf("Low byte: 0x%02X\n", low_byte);
    printf("Reassembled: 0x%04X\n", reassembled_value);

    return 0;
}
```

### Notes:
- Use `uint8_t` for byte-sized variables.
- The bitwise AND with `0xFF` ensures you only get the lower 8 bits.
- Shifting the high byte left by 8 bits places it back into the high position.
- Combining with bitwise OR reconstructs the original 16-bit value.

This approach is portable and works well with the CCS PCW C compiler.

