    try:
        response = await session.get(url, headers=headers)
        if response.status_code == 401:
            // Unauthorized, token might be expired
            token = get_token()
            headers['Authorization'] = 'Bearer ' + token
            response = await session.get(url, headers=headers)
        data = await response.json()
        return data
    except Exception as e:
