Modifying the sample rate of an input device (such as a microphone) in Windows programmatically is not straightforward because Windows audio devices typically do not allow direct modification of their hardware settings via the standard APIs. Instead, the sample rate is usually determined by the device driver and the current audio format configuration.

However, you can influence the sample rate used by an input device when opening an audio stream with the Windows Multimedia API (waveIn* functions) or the Core Audio APIs (WASAPI). The common approach is to specify the desired sample rate in the `WAVEFORMATEX` structure when opening the device.

### Using the Windows Multimedia API (waveIn*)

Here's a basic example of how to set the sample rate when opening a wave input device:

```c
#include <windows.h>
#include <mmsystem.h>
#include <stdio.h>

#pragma comment(lib, "winmm.lib")

int main() {
    HWAVEIN hWaveIn;
    WAVEFORMATEX wf;

    // Specify the desired sample rate, e.g., 44100 Hz
    wf.wFormatTag = WAVE_FORMAT_PCM;
    wf.nChannels = 1; // mono
    wf.nSamplesPerSec = 44100; // desired sample rate
    wf.wBitsPerSample = 16; // bits per sample
    wf.nBlockAlign = (wf.wBitsPerSample / 8) * wf.nChannels;
    wf.nAvgBytesPerSec = wf.nSamplesPerSec * wf.nBlockAlign;
    wf.cbSize = 0;

    MMRESULT result = waveInOpen(&hWaveIn, WAVE_MAPPER, &wf, 0, 0, CALLBACK_NULL);
    if (result != MMSYSERR_NOERROR) {
        printf("Failed to open wave input device. Error: %d\n", result);
        return 1;
    }

    printf("Wave input device opened with sample rate: %d Hz\n", wf.nSamplesPerSec);

    // Remember to close the device when done
    waveInClose(hWaveIn);
    return 0;
}
```

**Note:**  
- The `waveInOpen` function attempts to open a device with the specified format.  
- The actual device may not support the requested sample rate; in that case, `waveInOpen` may fail or the device may choose a different format.  
- To ensure the device supports the format, you can enumerate supported formats or use `waveInGetDevCaps` to query capabilities.

### Using Core Audio (WASAPI)

For more advanced control, including setting the sample rate, you can use the Windows Core Audio APIs (WASAPI). This involves:

1. Enumerating audio endpoints.
2. Activating an `IAudioClient`.
3. Initializing the client with the desired format, including sample rate.

Here's a simplified outline:

```c
#include <windows.h>
#include <mmdeviceapi.h>
#include <audioclient.h>
#include <initguid.h>
#include <stdio.h>

int main() {
    HRESULT hr;
    IMMDeviceEnumerator *pEnumerator = NULL;
    IMMDevice *pDevice = NULL;
    IAudioClient *pAudioClient = NULL;
    WAVEFORMATEX *pwfx = NULL;

    // Initialize COM
    hr = CoInitialize(NULL);
    if (FAILED(hr)) {
        printf("CoInitialize failed\n");
        return -1;
    }

    // Create device enumerator
    hr = CoCreateInstance(&CLSID_MMDeviceEnumerator, NULL, CLSCTX_ALL,
                          &IID_IMMDeviceEnumerator, (void**)&pEnumerator);
    if (FAILED(hr)) {
        printf("Failed to create device enumerator\n");
        CoUninitialize();
        return -1;
    }

    // Get default audio input device
    hr = pEnumerator->lpVtbl->GetDefaultAudioEndpoint(pEnumerator, eCapture, eConsole, &pDevice);
    if (FAILED(hr)) {
        printf("Failed to get default audio input device\n");
        pEnumerator->lpVtbl->Release(pEnumerator);
        CoUninitialize();
        return -1;
    }

    // Activate the audio client
    hr = pDevice->lpVtbl->Activate(pDevice, &IID_IAudioClient, CLSCTX_ALL, NULL, (void**)&pAudioClient);
    if (FAILED(hr)) {
        printf("Failed to activate audio client\n");
        pDevice->lpVtbl->Release(pDevice);
        pEnumerator->lpVtbl->Release(pEnumerator);
        CoUninitialize();
        return -1;
    }

    // Define desired format
    WAVEFORMATEX desiredFormat = {0};
    desiredFormat.wFormatTag = WAVE_FORMAT_PCM;
    desiredFormat.nChannels = 1;
    desiredFormat.nSamplesPerSec = 44100; // desired sample rate
    desiredFormat.wBitsPerSample = 16;
    desiredFormat.nBlockAlign = (desiredFormat.wBitsPerSample / 8) * desiredFormat.nChannels;
    desiredFormat.nAvgBytesPerSec = desiredFormat.nSamplesPerSec * desiredFormat.nBlockAlign;

    // Initialize the client with the desired format
    hr = pAudioClient->lpVtbl->Initialize(pAudioClient,
                                          AUDCLNT_SHAREMODE_SHARED,
                                          0,
                                          10000000, // buffer duration in 100-ns units
                                          0,
                                          &desiredFormat,
                                          NULL);
    if (FAILED(hr)) {
        printf("Failed to initialize audio client with desired format\n");
        pAudioClient->lpVtbl->Release(pAudioClient);
        pDevice->lpVtbl->Release(pDevice);
        pEnumerator->lpVtbl->Release(pEnumerator);
        CoUninitialize();
        return -1;
    }

    printf("Audio client initialized with sample rate: %d Hz\n", desiredFormat.nSamplesPerSec);

    // Cleanup
    pAudioClient->lpVtbl->Release(pAudioClient);
    pDevice->lpVtbl->Release(pDevice);
    pEnumerator->lpVtbl->Release(pEnumerator);
    CoUninitialize();

    return 0;
}
```

**Note:**  
- The actual support for the desired format depends on the device capabilities.  
- You should query the device for supported formats before initializing.  
- Proper error handling and format negotiation are necessary for production code.

---

### Summary

