## Step 3: Implement `main.js` (UI Logic)

```js
// main.js

const csInterface = new CSInterface();

const apiKeyInput = document.getElementById('apiKey');
const voiceSelect = document.getElementById('voiceSelect');
const textInput = document.getElementById('textInput');
const threeXCheckbox = document.getElementById('threeX');
const loadVoicesBtn = document.getElementById('loadVoices');

let voices = [];

// Load voices on button click
loadVoicesBtn.onclick = () => {
  const apiKey = apiKeyInput.value.trim();
  if (!apiKey) {
    alert('Please enter your API key.');
    return;
  }
  fetchVoices(apiKey);
};

// Fetch available voices from ElevenLabs
function fetchVoices(apiKey) {
  fetch('https://api.elevenlabs.io/v1/voices', {
    headers: { 'xi-api-key': apiKey }
  })
  .then(res => res.json())
  .then(data => {
    voices = data.voices || [];
    populateVoices();
  })
  .catch(err => alert('Error fetching voices: ' + err));
}

function populateVoices() {
  voiceSelect.innerHTML = '';
  voices.forEach(voice => {
    const option = document.createElement('option');
    option.value = voice.voice_id;
    option.textContent = voice.name;
    voiceSelect.appendChild(option);
  });
}

// Handle Enter key in text input
textInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    triggerSpeech();
  }
});

function triggerSpeech() {
  const apiKey = apiKeyInput.value.trim();
  const voiceId = voiceSelect.value;
  const text = textInput.value.trim();
  const isThreeX = threeXCheckbox.checked;

  if (!apiKey || !voiceId || !text) {
    alert('Please fill in all fields.');
    return;
  }

  if (isThreeX) {
    // Send three requests simultaneously
    for (let i = 0; i < 3; i++) {
      sendSpeechRequest(apiKey, voiceId, text, i === 0);
    }
  } else {
    sendSpeechRequest(apiKey, voiceId, text, true);
  }
}

// Send API request to generate speech
function sendSpeechRequest(apiKey, voiceId, text, isPrimary) {
  fetch(`https://api.elevenlabs.io/v1/text-to-speech/${voiceId}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'xi-api-key': apiKey
    },
    body: JSON.stringify({ text: text, voice_settings: {} })
  })
  .then(res => res.arrayBuffer())
  .then(buffer => {
    // Save MP3 locally
    const blob = new Blob([buffer], { type: 'audio/mpeg' });
    const reader = new FileReader();
    reader.onload = () => {
      const arrayBuffer = reader.result;
      // Send to ExtendScript for import
      const base64Data = btoa(String.fromCharCode(...new Uint8Array(arrayBuffer)));
      // Generate a filename
      const filename = `eleven_${Date.now()}_${Math.random().toString(36).substr(2, 5)}.mp3`;
      // Call ExtendScript to save and import
      csInterface.evalScript(`importAudio("${base64Data}", "${filename}", ${isPrimary})`);
    };
    reader.readAsArrayBuffer(blob);
  })
  .catch(err => {
    alert('Error generating speech: ' + err);
  });
}
```

