## Step 4: Implement ExtendScript `importAudio.jsx`

This script receives base64 MP3 data, decodes it, saves it to disk, and imports into a new composition.

```jsx
// jsx/importAudio.jsx

function importAudio(base64Data, filename, isPrimary) {
  try {
    // Decode base64
    var binaryString = atob(base64Data);
    var len = binaryString.length;
    var bytes = new Uint8Array(len);
    for (var i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }

    // Save to temp folder
    var tempFolder = Folder.temp;
    var filePath = tempFolder.fsName + "/" + filename;
    var file = new File(filePath);
    file.encoding = "BINARY";
    file.open("w");
    file.write(bytes);
    file.close();

    // Import into AE
    var importOptions = new ImportOptions(File(filePath));
    var importedFile = app.project.importFile(importOptions);

    // Create new composition
    var compName = "ElevenAudio_" + Date.now();
    var comp = app.project.items.addComp(compName, importedFile.width, importedFile.height, 1, importedFile.duration, 30);
    var layer = comp.layers.add(importedFile);

    // If primary, set as active comp
    if (isPrimary) {
      app.project.activeItem = comp;
    }

    // Optional: cleanup temp file after import
    // file.remove();

  } catch (e) {
    alert("Error importing audio: " + e.toString());
  }
}
```

