    const spaceGeo = new THREE.SphereGeometry(2000, 64, 64);
    const spaceMat = new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.BackSide });
    space = new THREE.Mesh(spaceGeo, spaceMat);
    scene.add(space);

    // Rocket
    const rocketGeo = new THREE.CylinderGeometry(2, 2, 10, 16);
    const rocketMat = new THREE.MeshStandardMaterial({ color: 0xff0000 });
    rocket = new THREE.Mesh(rocketGeo, rocketMat);
    rocket.position.y = 5;
    scene.add(rocket);

    // Rocket nose cone
    const coneGeo = new THREE.ConeGeometry(2, 4, 16);
    const coneMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
    const nose = new THREE.Mesh(coneGeo, coneMat);
    nose.position.y = 7;
    rocket.add(nose);

    // Rocket thruster flame
    const flameGeo = new THREE.ConeGeometry(1.5, 4, 16);
    const flameMat = new THREE.MeshBasicMaterial({ color: 0xffa500 });
    flame = new THREE.Mesh(flameGeo, flameMat);
    flame.position.y = -5;
    rocket.add(flame);
    flame.visible = false;

    // Handle window resize
    window.addEventListener('resize', onWindowResize, false);

    // Launch button
    document.getElementById('launchButton').addEventListener('click', () => {
      if (!isLaunching) {
        startLaunch();
      }
    });
  }

  function onWindowResize() {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
  }

  function startLaunch() {
    isLaunching = true;
    altitude = 0;
    velocity = 0;
    stage = 'ground';
    // Reset rocket position
    rocket.position.set(0, 5, 0);
    // Show flame
    flame.visible = true;
    // Clear smoke particles
    smokeParticles.forEach(p => scene.remove(p));
    smokeParticles = [];
  }

  function animate() {
    requestAnimationFrame(animate);
    const delta = clock.getDelta();

    if (isLaunching) {
      updateLaunch(delta);
    }

    renderer.render(scene, camera);
  }

  function updateLaunch(delta) {
    // Simple physics: v = v + a * dt, s = s + v * dt
    // Apply thrust if below max altitude
    if (altitude < maxAltitude) {
      velocity += thrust + gravity;
    } else {
      // Reached max altitude, start falling or stop thrust
      velocity += gravity;
    }

    altitude += velocity;

    if (altitude < 0) {
      altitude = 0;
      velocity = 0;
      // Launch complete
      isLaunching = false;
      flame.visible = false;
    }

    // Update rocket position
    rocket.position.y = altitude + 5; // base height offset

    // Update camera to follow rocket
    camera.position.x = rocket.position.x + 100;
    camera.position.y = rocket.position.y + 50;
    camera.position.z = rocket.position.z + 200;
    camera.lookAt(rocket.position);

    // Change stage based on altitude
    if (altitude > 300 && stage === 'ground') {
      stage = 'atmosphere';
    }
    if (altitude > 800 && stage === 'atmosphere') {
      stage = 'space';
      // Optional: change background or add stars
    }

    // Show flame when thrusting
    flame.visible = true;

    // Generate smoke particles
    generateSmoke();

    // Animate smoke particles
    animateSmoke(delta);
  }

  function generateSmoke() {
    // Create smoke particles at the flame position
    const particleGeo = new THREE.SphereGeometry(0.2, 8, 8);
    const particleMat = new THREE.MeshBasicMaterial({ color: 0x555555, transparent: true, opacity: 0.5 });
    const particle = new THREE.Mesh(particleGeo, particleMat);
    particle.position.copy(rocket.position);
    particle.position.y -= 5; // at flame position
    scene.add(particle);
    smokeParticles.push({ mesh: particle, life: 1.0 });
  }

  function animateSmoke(delta) {
    // Update smoke particles
    for (let i = smokeParticles.length - 1; i >= 0; i--) {
      const p = smokeParticles[i];
      p.mesh.position.y += 0.5 * delta; // drift upward
      p.life -= delta;
      p.mesh.material.opacity = p.life; // fade out
      if (p.life <= 0) {
        scene.remove(p.mesh);
        smokeParticles.splice(i, 1);
      }
    }
  }
</script>
</body>
</html>
```

Certainly! To run a task in the background and retrieve its outcome in C++, you can use `std::async` from the `<future>` header. This allows you to run a function asynchronously and get its result later.

Here's an example of a generic function that runs a task in the background and returns a `std::future` to obtain the outcome:

```cpp
#include <iostream>
#include <future>
#include <chrono>

// Example task function
int exampleTask(int value) {
    // Simulate some work
    std::this_thread::sleep_for(std::chrono::seconds(2));
    return value * 2;
}

// Function to run a task asynchronously
template <typename Func, typename... Args>
auto runInBackground(Func&& func, Args&&... args) {
    // Launch the task asynchronously
    return std::async(std::launch::async, std::forward<Func>(func), std::forward<Args>(args)...);
}

int main() {
    // Start the background task
    auto futureResult = runInBackground(exampleTask, 10);

    // Do other work here
    std::cout << "Task is running in the background...\n";

    // Wait for the result
    int result = futureResult.get();

    std::cout << "Result of background task: " << result << std::endl;

    return 0;
}
```

### Explanation:
- `runInBackground` is a template function that accepts any callable and its arguments, launching it asynchronously.
- It returns a `std::future` object, which can be used to retrieve the result once the task completes.
- In `main()`, we start the task, do some other work, and then wait for the result with `.get()`.

### Notes:
- Using `std::async` with `std::launch::async` ensures the task runs on a separate thread.
- You can adapt this pattern to any task function, including lambdas or functors.

