Certainly! Here's a simple example of a basic HTTP server in C for Linux that serves files from a specified directory. The server takes two command-line arguments:

- The port number to listen on
- The directory path to serve files from

This example uses standard socket programming and basic file I/O. It handles simple GET requests and responds with the requested file if it exists, or a 404 error if not.

**Note:** This is a minimal example for educational purposes. It does not handle many edge cases, concurrent connections, or security considerations.

---

### Basic HTTP Server in C

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/stat.h>
#include <dirent.h>

#define BUFFER_SIZE 4096

// Function to send a response
void send_response(int client_fd, const char *status, const char *content_type, const void *body, size_t body_size) {
    char header[BUFFER_SIZE];
    int header_length = snprintf(header, sizeof(header),
        "HTTP/1.1 %s\r\n"
        "Content-Type: %s\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n",
        status, content_type, body_size);
    write(client_fd, header, header_length);
    write(client_fd, body, body_size);
}

// Function to get content type based on file extension
const char* get_content_type(const char *path) {
    const char *ext = strrchr(path, '.');
    if (!ext) return "application/octet-stream";

    if (strcmp(ext, ".html") == 0 || strcmp(ext, ".htm") == 0)
        return "text/html";
    if (strcmp(ext, ".jpg") == 0 || strcmp(ext, ".jpeg") == 0)
        return "image/jpeg";
    if (strcmp(ext, ".png") == 0)
        return "image/png";
    if (strcmp(ext, ".gif") == 0)
        return "image/gif";
    if (strcmp(ext, ".css") == 0)
        return "text/css";
    if (strcmp(ext, ".js") == 0)
        return "application/javascript";
    if (strcmp(ext, ".txt") == 0)
        return "text/plain";

    return "application/octet-stream";
}

// Function to serve a file
void serve_file(int client_fd, const char *filepath) {
    int fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        // File not found
        const char *not_found = "<h1>404 Not Found</h1>";
        send_response(client_fd, "404 Not Found", "text/html", not_found, strlen(not_found));
        return;
    }

    struct stat st;
    if (fstat(fd, &st) < 0) {
        close(fd);
        const char *error_msg = "<h1>500 Internal Server Error</h1>";
        send_response(client_fd, "500 Internal Server Error", "text/html", error_msg, strlen(error_msg));
        return;
    }

    // Read file content
    void *file_content = malloc(st.st_size);
    if (!file_content) {
        close(fd);
        const char *error_msg = "<h1>500 Internal Server Error</h1>";
        send_response(client_fd, "500 Internal Server Error", "text/html", error_msg, strlen(error_msg));
        return;
    }

    ssize_t read_bytes = read(fd, file_content, st.st_size);
    close(fd);
    if (read_bytes != st.st_size) {
        free(file_content);
        const char *error_msg = "<h1>500 Internal Server Error</h1>";
        send_response(client_fd, "500 Internal Server Error", "text/html", error_msg, strlen(error_msg));
        return;
    }

    // Send the file content
    send_response(client_fd, "200 OK", get_content_type(filepath), file_content, st.st_size);
    free(file_content);
}

// Function to handle a client connection
void handle_client(int client_fd, const char *base_dir) {
    char buffer[BUFFER_SIZE];
    ssize_t received = read(client_fd, buffer, sizeof(buffer) - 1);
    if (received <= 0) {
        close(client_fd);
        return;
    }
    buffer[received] = '\0';

    // Parse the request line
    char method[16], path[256], protocol[16];
    sscanf(buffer, "%15s %255s %15s", method, path, protocol);

    if (strcmp(method, "GET") != 0) {
        // Only handle GET
        const char *not_allowed = "<h1>405 Method Not Allowed</h1>";
        send_response(client_fd, "405 Method Not Allowed", "text/html", not_allowed, strlen(not_allowed));
        close(client_fd);
        return;
    }

    // Prevent directory traversal
    if (strstr(path, "..")) {
        const char *forbidden = "<h1>403 Forbidden</h1>";
        send_response(client_fd, "403 Forbidden", "text/html", forbidden, strlen(forbidden));
        close(client_fd);
        return;
    }

    // Default to "/" if root
    if (strcmp(path, "/") == 0) {
        strcpy(path, "/index.html");
    }

    // Construct full filepath
    char filepath[BUFFER_SIZE];
    snprintf(filepath, sizeof(filepath), "%s%s", base_dir, path);

    // Serve the file
    serve_file(client_fd, filepath);

    close(client_fd);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <port> <directory>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int port = atoi(argv[1]);
    const char *base_dir = argv[2];

    // Check if directory exists
    struct stat st;
    if (stat(base_dir, &st) != 0 || !S_ISDIR(st.st_mode)) {
        fprintf(stderr, "Error: Directory '%s' does not exist or is not a directory.\n", base_dir);
        exit(EXIT_FAILURE);
    }

    // Create socket
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Bind socket
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(port);

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    if (bind(server_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Listen
    if (listen(server_fd, 10) < 0) {
        perror("listen");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Serving directory '%s' on port %d\n", base_dir, port);

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);
        if (client_fd < 0) {
            perror("accept");
            continue;
        }

        handle_client(client_fd, base_dir);
    }

    close(server_fd);
    return 0;
}
```

