  // Ground (for collision)
  let groundGeo = new THREE.PlaneGeometry(2000, 50);
  let groundMat = new THREE.MeshBasicMaterial({color: 0x228B22});
  let ground = new THREE.Mesh(groundGeo, groundMat);
  ground.position.y = -250;
  scene.add(ground);

  // Bird
  let birdGeo = new THREE.SphereGeometry(20, 16, 16);
  let birdMat = new THREE.MeshBasicMaterial({color: 0xffd700});
  bird = new THREE.Mesh(birdGeo, birdMat);
  bird.position.set(0, 0, 0);
  scene.add(bird);

  // Generate initial pipes
  for(let i=1; i<=5; i++) {
    createPipe(i * pipeSpacing);
  }
}

function createPipe(xPos) {
  let gapY = (Math.random() * 200) - 100; // Random vertical position
  let topPipeGeo = new THREE.BoxGeometry(pipeWidth, 300, 20);
  let bottomPipeGeo = new THREE.BoxGeometry(pipeWidth, 300, 20);
  let pipeMat = new THREE.MeshBasicMaterial({color: 0x006400});

  let topPipe = new THREE.Mesh(topPipeGeo, pipeMat);
  topPipe.position.set(xPos, gapY + gapSize/2 + 150, 0);
  topPipe.rotation.z = Math.PI;
  scene.add(topPipe);

  let bottomPipe = new THREE.Mesh(bottomPipeGeo, pipeMat);
  bottomPipe.position.set(xPos, gapY - gapSize/2 - 150, 0);
  scene.add(bottomPipe);

  pipes.push({top: topPipe, bottom: bottomPipe, x: xPos, passed: false});
}

function onWindowResize() {
  camera.aspect = window.innerWidth/window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
}

function animate() {
  requestAnimationFrame(animate);
  if (gameOver) {
    renderer.render(scene, camera);
    return;
  }

  let delta = clock.getDelta();

  // Bird physics
  if (mouseDown) {
    velocityY = lift;
  } else {
    velocityY += gravity;
  }
  bird.position.y += velocityY;

  // Camera slow follow
  camera.position.x += (bird.position.x - camera.position.x) * 0.02;
  camera.position.y += (bird.position.y - camera.position.y) * 0.02;
  camera.lookAt(bird.position.x, bird.position.y, 0);

  // Move pipes
  for (let pipe of pipes) {
    pipe.x -= pipeSpeed;
    pipe.top.position.x = pipe.x;
    pipe.bottom.position.x = pipe.x;

    // Check for passing pipes
    if (!pipe.passed && pipe.x + pipeWidth/2 < bird.position.x) {
      score++;
      pipe.passed = true;
    }

    // Remove pipes off screen
    if (pipe.x < -window.innerWidth/2 - pipeWidth) {
      scene.remove(pipe.top);
      scene.remove(pipe.bottom);
    }
  }

  // Remove off-screen pipes and add new ones
  if (pipes.length > 0 && pipes[0].x < -window.innerWidth/2 - pipeWidth) {
    pipes.shift();
    createPipe(pipes.length > 0 ? pipes[pipes.length-1].x + pipeSpacing : bird.position.x + pipeSpacing);
  }

  // Collision detection
  for (let pipe of pipes) {
    if (checkCollision(bird, pipe.top) || checkCollision(bird, pipe.bottom)) {
      endGame();
    }
  }

  // Ground collision
  if (bird.position.y - 20 <= -250 + 25) { // ground level + half height
    endGame();
  }

  renderer.render(scene, camera);
}

function checkCollision(bird, pipe) {
  let bx = bird.position.x;
  let by = bird.position.y;
  let bw = 20;
  let bh = 20;

  let px = pipe.position.x;
  let py = pipe.position.y;
  let pw = pipe.geometry.parameters.width;
  let ph = pipe.geometry.parameters.height;

  return (Math.abs(bx - px) < (bw + pw)/2) && (Math.abs(by - py) < (bh + ph)/2);
}

function endGame() {
  alert("Game Over! Score: " + score);
  location.reload();
}
</script>
