Certainly! Below is a comprehensive example of a TypeScript application that uses `http-middleware-proxy` to intercept and modify both POST request data and response data. It supports both JSON and NDJSON (newline-delimited JSON) response formats.

### Prerequisites

1. **Node.js** installed.
2. Initialize your project:

```bash
mkdir proxy-server
cd proxy-server
npm init -y
npm install http-middleware-proxy typescript @types/node ts-node
```

3. Create a `tsconfig.json`:

```json
{
  "compilerOptions": {
    "target": "ES2020",
    "module": "CommonJS",
    "outDir": "./dist",
    "strict": true,
    "esModuleInterop": true
  },
  "include": ["src"]
}
```

### Implementation

Create a directory `src` and inside it, a file `index.ts`:

```typescript
import { createProxyMiddleware } from 'http-middleware-proxy';
import * as http from 'http';

// Helper function to determine if content is NDJSON
function isNDJSON(contentType: string): boolean {
  return contentType.includes('application/x-ndjson') || contentType.includes('application/ndjson');
}

// Middleware to modify POST request data
function modifyRequestBody(req: http.IncomingMessage, body: Buffer): Buffer {
  const contentType = req.headers['content-type'] || '';

  if (contentType.includes('application/json')) {
    // Parse JSON
    const jsonData = JSON.parse(body.toString());
    // Modify data as needed, e.g., add a property
    jsonData['intercepted'] = true;
    // Return stringified JSON
    return Buffer.from(JSON.stringify(jsonData));
  } else if (isNDJSON(contentType)) {
    // NDJSON: parse each line
    const lines = body.toString().split('\n').filter(line => line.trim() !== '');
    const jsonObjects = lines.map(line => JSON.parse(line));
    // Modify each object
    jsonObjects.forEach(obj => {
      obj['intercepted'] = true;
    });
    // Re-serialize
    const modifiedLines = jsonObjects.map(obj => JSON.stringify(obj));
    return Buffer.from(modifiedLines.join('\n') + '\n');
  } else {
    // For other content types, return as-is
    return body;
  }
}

// Middleware to modify response data
function modifyResponseBody(res: http.IncomingMessage, body: Buffer): Buffer {
  const contentType = res.headers['content-type'] || '';

  if (contentType.includes('application/json')) {
    // Parse JSON
    const jsonData = JSON.parse(body.toString());
    // Modify data
    jsonData['intercepted'] = true;
    return Buffer.from(JSON.stringify(jsonData));
  } else if (isNDJSON(contentType)) {
    // NDJSON: parse each line
    const lines = body.toString().split('\n').filter(line => line.trim() !== '');
    const jsonObjects = lines.map(line => JSON.parse(line));
    // Modify each object
    jsonObjects.forEach(obj => {
      obj['intercepted'] = true;
    });
    // Re-serialize
    const modifiedLines = jsonObjects.map(obj => JSON.stringify(obj));
    return Buffer.from(modifiedLines.join('\n') + '\n');
  } else {
    // For other content types, return as-is
    return body;
  }
}

// Create the proxy middleware
const proxy = createProxyMiddleware({
  // Target server to proxy to
  target: 'http://localhost:3001', // Change to your target server
  changeOrigin: true,

  // Intercept and modify request data
  onRequest: async (req, res, bodyBuffer) => {
    if (req.method === 'POST') {
      // Modify request body
      const modifiedBody = modifyRequestBody(req, bodyBuffer);
      // Replace the request body with the modified one
      req.body = modifiedBody;
    }
  },

  // Intercept and modify response data
  onResponse: async (req, res, bodyBuffer) => {
    // Modify response body
    const modifiedBody = modifyResponseBody(res, bodyBuffer);
    return modifiedBody;
  }
});

// Create and start the server
const server = http.createServer((req, res) => {
  proxy(req, res);
});

const PORT = 8080;
server.listen(PORT, () => {
  console.log(`Proxy server listening on port ${PORT}`);
});
```

### How it works:

- The proxy intercepts all requests and responses.
- For POST requests:
  - It parses the body based on `Content-Type`.
  - Adds an `intercepted: true` property.
  - Replaces the request body with the modified data.
- For responses:
  - It inspects the `Content-Type`.
  - Parses and modifies JSON and NDJSON data similarly.
  - Adds an `intercepted: true` property to each JSON object.
- Supports both JSON (`application/json`) and NDJSON (`application/x-ndjson` or `application/ndjson`).

### Usage

1. Run your target server on `http://localhost:3001` (or change the target in the code).
2. Start the proxy server:

```bash
npx ts-node src/index.ts
```

3. Send POST requests with JSON or NDJSON payloads to `http://localhost:8080`, and observe the modifications.

---

**Note:** Make sure your target server is running and accessible. Adjust the target URL as needed.

---

